def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_me, last_opp = history[-1]
    if n == 1:
        return 'D' if last_opp == 'D' else 'C'

    opp_c_total = 0
    recent_opp_start = n - 8
    if recent_opp_start < 0:
        recent_opp_start = 0
    recent_opp_c = 0

    for i in range(n):
        if history[i][1] == 'C':
            opp_c_total += 1
            if i >= recent_opp_start:
                recent_opp_c += 1

    cond_start = n - 10
    if cond_start < 1:
        cond_start = 1

    after_c_t = after_d_t = coop_c_t = coop_d_t = 0
    after_c_r = after_d_r = coop_c_r = coop_d_r = 0

    for i in range(1, n):
        prev = history[i - 1][0]
        opp = history[i][1]
        opp_is_c = opp == 'C'

        if prev == 'C':
            after_c_t += 1
            if opp_is_c:
                coop_c_t += 1
            if i >= cond_start:
                after_c_r += 1
                if opp_is_c:
                    coop_c_r += 1
        else:
            after_d_t += 1
            if opp_is_c:
                coop_d_t += 1
            if i >= cond_start:
                after_d_r += 1
                if opp_is_c:
                    coop_d_r += 1

    if after_c_t > 0:
        qC_tot = float(coop_c_t) / float(after_c_t)
    else:
        qC_tot = float(opp_c_total) / float(n)

    if after_c_r >= 4:
        qC_rec = float(coop_c_r) / float(after_c_r)
    else:
        qC_rec = qC_tot

    qC = qC_rec if after_c_r >= 6 else qC_tot

    if after_d_t > 0:
        qD_tot = float(coop_d_t) / float(after_d_t)
    else:
        qD_tot = -1.0

    if after_d_r >= 4:
        qD_rec = float(coop_d_r) / float(after_d_r)
    else:
        qD_rec = qD_tot

    qD = qD_rec if after_d_r >= 4 else qD_tot

    # Persistent recent defection against our cooperation: stop rewarding.
    if last_opp == 'D' and last_me == 'C' and n >= 5 and recent_opp_c <= 2:
        return 'D'

    # No action-history evidence yet that our D gets rewarded.
    if after_d_t == 0:
        if qC <= 0.5:
            return 'D'

        # If we just made a first test defection, cooperate once unless the
        # opponent is already looking unresponsive/defective.
        if last_me == 'D':
            return 'C' if qC >= 0.8 else 'D'

        # Make a single controlled test against a long cooperative pattern.
        if n >= 24 and qC >= 0.8:
            return 'D'

        return 'C'

    # If cooperation often follows our D, the opponent is weakly or not
    # responsive; continuous D is usually better than stable CC.
    exploit_threshold = 0.75 * qC - 0.20
    if exploit_threshold < 0.25:
        exploit_threshold = 0.25
    if qD >= exploit_threshold:
        return 'D'

    # Current opponent move is most likely predicted by our previous move.
    if last_me == 'D':
        # Current opponent likely D. Defect unless the opponent rewards our C
        # enough that a one-round recovery is worth the sucker payoff.
        if qC <= 0.4 or 3.0 * qC <= 1.0 + 4.0 * qD:
            return 'D'
        return 'C'

    # Current opponent move is most likely predicted by our previous C.
    # If evidence is still thin and the opponent is not a strong cooperator,
    # take one more short test to avoid mistaking an unresponsive random/
    # cooperative opponent for a retaliator.
    if after_d_t < 3 and qD <= 0.35:
        if qC_tot < 0.93 or qC < 0.85:
            return 'D'

    if qC <= 0.4:
        return 'D'

    return 'C'
